msg.children = [];
msg.messageId = this.makeMessageId(msg);
if (aArgs.age) {
  const age = aArgs.age;
  // start from 'now'
  let ts = new Date().valueOf();
  if (age.minutes) {
    ts -= age.minutes * 60 * 1000;
  }
  if (age.hours) {
    ts -= age.hours * 60 * 60 * 1000;
  }
  if (age.days) {
    ts -= age.days * 24 * 60 * 60 * 1000;
  }
  if (age.weeks) {
    ts -= age.weeks * 7 * 24 * 60 * 60 * 1000;
  }
  msg.date = new Date(ts);
} else if (aArgs.date) {
  msg.date = aArgs.date;
} else {
  msg.date = this.makeDate();
}
